    for (let i = 0; i < old.length; i++) old[i].remove();
    const F = OptionsPanel.features(host);
    const ov = PlayerUI.overlay(container, "data-options");
    let closed = false;
    const close = function () { if (closed) return; closed = true; if (ov.parentNode) ov.remove(); if (ctx.onClose) ctx.onClose(); };
