        sel.setAttribute("data-opt", "quality");
        [["auto", "Auto"], ["low", "\xC9conomie"], ["high", "Maximale"]].forEach(function (q) { const o = document.createElement("option"); o.value = q[0]; o.textContent = q[1]; if (settings.quality === q[0]) o.selected = true; sel.appendChild(o); });
        sel.addEventListener("change", function () { change({ quality: sel.value }); });
