        const im = hmk("img", { width: "100%", height: L.fill ? "100%" : "auto", display: "block", objectFit: L.fit || "cover", pointerEvents: "none" });
        im.setAttribute("alt", ""); im.setAttribute("draggable", "false"); im.setAttribute("decoding", "async");
        im.onerror = function () { im.style.visibility = "hidden"; };
