          v.muted = L.muted !== false; v.setAttribute("muted", ""); v.loop = L.loop !== false; v.setAttribute("playsinline", ""); v.playsInline = true; v.setAttribute("preload", "none");
          const fail = function () { v.style.opacity = "0"; fb.style.display = L.fallback ? "block" : "none"; };
